{"compatibility":"as-is","safety_note_md":"# SafeStan Safety Note

Compatibility: as-is.

Protected data: none.

Generated files: `model_safe.stan`, `data_safe.json`.

No changes were required. The program has no `model` block, no parameters, and no sampling statements, so it does not condition on any protected data. All declared data variables are context/configuration inputs used only for deterministic index construction.
","model_safe_stan":"data {
  // Main factor indices
  int<lower=0> N_main_factors;
  array[N_main_factors] int<lower=0> N_main_factor_levels;

  // First-order interaction indices
  int<lower=0> N_inter1_factors;
  array[N_inter1_factors] int<lower=0> N_inter1_factor_levels;

  // Second-order factor indices
  int<lower=0> N_inter2_factors;
  array[N_inter2_factors] int<lower=0> N_inter2_factor_levels;
}

transformed data {
  int N_all_main = sum(N_main_factor_levels);
  int N_all_inter1 = sum(N_inter1_factor_levels);
  int N_all_inter2 = sum(N_inter2_factor_levels);
}

generated quantities {
  // Flattened indices
  int<lower=0> N_all_main_factor_levels = N_all_main;
  array[N_all_main] int<lower=1, upper=N_main_factors> packed_main_factor_idx;
  array[N_main_factors] int<lower=1, upper=N_all_main> main_factor_start_idx;
  array[N_main_factors] int<lower=1, upper=N_all_main> main_factor_end_idx;

  int<lower=0> N_all_inter1_factor_levels = N_all_inter1;
  array[N_all_inter1] int<lower=1, upper=N_inter1_factors> packed_inter1_factor_idx;
  array[N_inter1_factors] int<lower=1, upper=N_all_inter1> inter1_factor_start_idx;
  array[N_inter1_factors] int<lower=1, upper=N_all_inter1> inter1_factor_end_idx;

  int<lower=0> N_all_inter2_factor_levels = N_all_inter2;
  array[N_all_inter2] int<lower=1, upper=N_inter2_factors> packed_inter2_factor_idx;
  array[N_inter2_factors] int<lower=1, upper=N_all_inter2> inter2_factor_start_idx;
  array[N_inter2_factors] int<lower=1, upper=N_all_inter2> inter2_factor_end_idx;

  {
    int cumsum = 0;
    for (f in 1:N_main_factors) {
      main_factor_start_idx[f] = cumsum + 1;
      main_factor_end_idx[f] = cumsum + N_main_factor_levels[f];
      packed_main_factor_idx[main_factor_start_idx[f]:main_factor_end_idx[f]]
        = rep_array(f, N_main_factor_levels[f]);
      cumsum += N_main_factor_levels[f];
    }

    cumsum = 0;
    for (f in 1:N_inter1_factors) {
      inter1_factor_start_idx[f] = cumsum + 1;
      inter1_factor_end_idx[f] = cumsum + N_inter1_factor_levels[f];
      packed_inter1_factor_idx[inter1_factor_start_idx[f]:inter1_factor_end_idx[f]]
        = rep_array(f, N_inter1_factor_levels[f]);
      cumsum += N_inter1_factor_levels[f];
    }

    cumsum = 0;
    for (f in 1:N_inter2_factors) {
      inter2_factor_start_idx[f] = cumsum + 1;
      inter2_factor_end_idx[f] = cumsum + N_inter2_factor_levels[f];
      packed_inter2_factor_idx[inter2_factor_start_idx[f]:inter2_factor_end_idx[f]]
        = rep_array(f, N_inter2_factor_levels[f]);
      cumsum += N_inter2_factor_levels[f];
    }
  }
}
